{
  "packages": {
    "ui": {
      "role": "Low-level reusable React component library with Radix UI, Lexical editor, and utility exports",
      "depends_on": []
    },
    "web-core": {
      "role": "Shared React + TypeScript library for frontend features, hooks, and project-specific components used by both local and remote apps",
      "depends_on": ["ui"]
    },
    "local-web": {
      "role": "Tauri-based local desktop application entrypoint for Vibe",
      "depends_on": ["web-core", "ui"]
    },
    "remote-web": {
      "role": "Cloud/remote deployment web application entrypoint for Vibe",
      "depends_on": ["web-core", "ui"]
    },
    "shared": {
      "role": "Generated TypeScript types and schemas from Rust definitions, plus JWT utilities; used by all packages",
      "depends_on": []
    }
  },
  "direction": "Dependencies flow upward from foundation libraries (ui, shared) → shared library (web-core) → application entrypoints (local-web, remote-web); both apps are peers that reuse web-core."
}
```

